CREATE TABLE settings (`key` VARCHAR(80) PRIMARY KEY, `value` TEXT NOT NULL);
INSERT INTO settings VALUES ('site_name','Saee Life Herbal'),('logo_url','assets/logo.png'),('company_sponsor_code','COMPANY'),('contact_email',''),('contact_phone',''),('address',''),('facebook',''),('instagram',''),('youtube','');
CREATE TABLE members (id INT AUTO_INCREMENT PRIMARY KEY, member_code VARCHAR(32) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, phone VARCHAR(40) NOT NULL DEFAULT '', password_hash VARCHAR(255) NOT NULL, sponsor_id INT NULL, is_admin TINYINT NOT NULL DEFAULT 0, wallet DECIMAL(12,2) NOT NULL DEFAULT 0, address TEXT NULL, kyc_number VARCHAR(100) NULL, bank_name VARCHAR(160) NULL, bank_account VARCHAR(100) NULL, bank_ifsc VARCHAR(30) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(sponsor_id) REFERENCES members(id));
CREATE TABLE products (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, category VARCHAR(100) NOT NULL, description TEXT NOT NULL, price DECIMAL(12,2) NOT NULL, direct_commission DECIMAL(12,2) NOT NULL DEFAULT 0, grand_commission DECIMAL(12,2) NOT NULL DEFAULT 0, image VARCHAR(500) NOT NULL DEFAULT 'assets/product-bottle.jpg');
INSERT INTO products (name,category,description,price) VALUES ('Herbal Crop Booster','Plant Nutrition','A little extra care for healthier crops.',650),('Organic Plant Protector','Crop Protection','Thoughtful protection for your fields.',550),('Soil Health Enhancer','Soil Care','Good growth starts with healthy soil.',480),('Natural Growth Formula','Plant Nutrition','Nourishment for every growing season.',720);
CREATE TABLE slides (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255) NOT NULL, description TEXT NOT NULL, image VARCHAR(500) NOT NULL, duration INT NOT NULL DEFAULT 5000);
CREATE TABLE rules (id INT AUTO_INCREMENT PRIMARY KEY, threshold INT NOT NULL, amount DECIMAL(12,2) NOT NULL);
CREATE TABLE milestone_awards (member_id INT NOT NULL, rule_id INT NOT NULL, PRIMARY KEY(member_id,rule_id), FOREIGN KEY(member_id) REFERENCES members(id), FOREIGN KEY(rule_id) REFERENCES rules(id));
CREATE TABLE purchases (id INT AUTO_INCREMENT PRIMARY KEY, buyer_id INT NOT NULL, product_id INT NOT NULL, price DECIMAL(12,2) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(buyer_id) REFERENCES members(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE wallet_ledger (id INT AUTO_INCREMENT PRIMARY KEY, member_id INT NOT NULL, amount DECIMAL(12,2) NOT NULL, kind VARCHAR(40) NOT NULL, reference_id INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(member_id) REFERENCES members(id));
CREATE TABLE payouts (id INT AUTO_INCREMENT PRIMARY KEY, member_id INT NOT NULL, amount DECIMAL(12,2) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(member_id) REFERENCES members(id));
